function drawObjective(r){let friendly=r.owner==='friendly';ctx.save();ctx.translate(r.x,r.y);let pulse=(Math.sin(elapsed*2+r.id)+1)*.5;ctx.beginPath();ctx.arc(0,0,r.r+5+pulse*3,0,TAU);ctx.strokeStyle=friendly?'#a1c77f':'#e4b96e';ctx.globalAlpha=.25+pulse*.25;ctx.lineWidth=1;ctx.stroke();ctx.globalAlpha=1;ctx.beginPath();ctx.arc(0,0,r.r,0,TAU);ctx.fillStyle=friendly?'#4b6542':'#544b35';ctx.fill();ctx.strokeStyle=friendly?'#bad18e':'#dfbe77';ctx.lineWidth=1.5;ctx.stroke();ctx.beginPath();ctx.arc(0,0,r.r-5,-Math.PI/2,-Math.PI/2+TAU*(friendly?1:r.progress));ctx.strokeStyle=friendly?'#a7d482':'#d7ad66';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle=friendly?'#c3d99e':'#e2cb91';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(friendly?'✓':'⌖',0,1);ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle='#e2e2cf';ctx.font='bold 10px sans-serif';ctx.fillText(r.name,r.r+10,4);ctx.restore()}
function drawUnit(u,i,enemy=false){ctx.save();ctx.translate(u.x,u.y);if(!enemy&&i===selected){ctx.beginPath();ctx.arc(0,0,19,0,TAU);ctx.strokeStyle='#d2e0a1';ctx.lineWidth=1;ctx.globalAlpha=.8;ctx.stroke();ctx.globalAlpha=1}if(!enemy&&u.order){ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(u.order.x-u.x,u.order.y-u.y);ctx.strokeStyle='#9dc4d0';ctx.globalAlpha=.35;ctx.setLineDash([3,5]);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1}
ctx.beginPath();ctx.arc(0,0,enemy?12:13,0,TAU);ctx.fillStyle=enemy?'#894f45':'#486e7e';ctx.fill();ctx.strokeStyle=enemy?'#e08a75':'#a2cde0';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle=enemy?'#f0b4a1':'#d5e4d1';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(enemy?'×':u.type==='armor'?'▰':'✥',0,1);if(!enemy){ctx.fillStyle='#20281e';ctx.fillRect(-12,17,24,3);ctx.fillStyle='#9ac77a';ctx.fillRect(-12,17,24*u.hp/100,3)}ctx.restore()}
function draw(){if(!cw||!ch)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#1b271e';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);drawMap();regions.forEach(drawObjective);for(let e of enemies)drawUnit(e,e.id,true);for(let i=0;i<units.length;i++)drawUnit(units[i],i,false);
for(let p of particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-1,p.y-1,2,2)}ctx.globalAlpha=1;for(let t of tracers){ctx.globalAlpha=clamp(t.life*4,0,1);ctx.strokeStyle=t.color;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(t.x,t.y);ctx.lineTo(t.tx,t.ty);ctx.stroke()}ctx.globalAlpha=1;
