ctx.save();ctx.translate(947,72);ctx.strokeStyle='#d4dac5';ctx.fillStyle='#d4dac5';ctx.globalAlpha=.65;ctx.beginPath();ctx.moveTo(0,10);ctx.lineTo(0,-12);ctx.stroke();ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(-4,-7);ctx.lineTo(0,-9);ctx.lineTo(4,-7);ctx.closePath();ctx.fill();ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('N',0,-21);ctx.restore();ctx.strokeStyle='#e0e0cb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(895,666);ctx.lineTo(955,666);ctx.stroke();ctx.font='9px ui-monospace,monospace';ctx.fillStyle='#d1d6c6';ctx.fillText('2 km',913,659);ctx.restore();}

