function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function fire(from,to,color){tracers.push({x:from.x,y:from.y,tx:to.x,ty:to.y,color,life:.28});for(let i=0;i<4;i++)particles.push({x:to.x+rand(-5,5),y:to.y+rand(-5,5),life:rand(.25,.7),color})}
function update(dt){if(!playing||gameOver)return;elapsed+=dt*speed;
for(let u of units){if(u.order){let d=dist(u,u.order);if(d>7){let sp=(u.type==='armor'?42:34)*dt*speed,uX=(u.order.x-u.x)/d,uY=(u.order.y-u.y)/d;u.x+=uX*sp;u.y+=uY*sp;u.angle=Math.atan2(uY,uX)}else u.order=null}
 u.cool-=dt*speed;
 if(u.cool<=0){let target=null,best=155;for(let e of enemies){let d=dist(u,e);if(d<best){best=d;target=e}}if(target){fire(u,target,'#b9d7df');target.hp-=rand(8,15);u.cool=rand(.7,1.2);if(target.hp<=0){addEvent(timeLabel(),'Contato hostil neutralizado.');supply+=12;enemies.splice(enemies.indexOf(target),1)}}}
 for(let r of regions){if(dist(u,r)<r.r+5&&r.owner!=='friendly'){r.progress+=dt*.12*speed;if(r.progress>=1){r.owner='friendly';r.progress=1;addEvent(timeLabel(),`${r.name} assegurado.`);showToast(`${r.name} — sob controle aliado`);supply+=25}}}}
for(let e of enemies){e.cool-=dt*speed;let nearest=units[0],bd=999;for(let u of units){let d=dist(e,u);if(d<bd){bd=d;nearest=u}}if(bd<180&&nearest&&e.cool<=0){fire(e,nearest,'#df917c');nearest.hp-=rand(5,10);nearest.soldiers=Math.max(1,Math.round(nearest.soldiers*(nearest.hp/100)));e.cool=rand(.8,1.5);if(nearest.hp<=0){units.splice(units.indexOf(nearest),1);losses++;addEvent(timeLabel(),'Pelotão perdido em combate.');if(selected>=units.length)selected=Math.max(0,units.length-1)}}else{let t=units[0];if(t&&bd>150){e.x+=((t.x-e.x)/bd)*12*dt*speed;e.y+=((t.y-e.y)/bd)*12*dt*speed}}
 if(dist(e,{x:168,y:386})<100){base-=dt*.8*speed}}
for(let p of particles)p.life-=dt*speed;particles=particles.filter(p=>p.life>0);for(let t of tracers)t.life-=dt*speed;tracers=tracers.filter(t=>t.life>0);
let secured=regions.filter(r=>r.owner==='friendly').length;if(secured===4&&enemies.length===0){gameOver='VITÓRIA';playing=false;showToast('Missão concluída — corredor seguro');showEnd(true)}else if(base<=0||units.length===0){gameOver='DERROTA';playing=false;showToast('Operação encerrada');showEnd(false)}
}
function showEnd(win){document.getElementById('briefing').style.display='grid';let modal=document.querySelector('.modal');modal.innerHTML=`<div class="modal-kicker">${win?'OPERAÇÃO CONCLUÍDA':'OPERAÇÃO FRACASSADA'}</div><h1>${win?'Corredor assegurado':'Linha quebrada'}</h1><p>${win?'Todos os postos foram retomados e o abastecimento da frente está garantido.':'A força aliada perdeu a capacidade de continuar a operação.'}</p><div class="briefing-grid"><div><b>SETOR</b><span>${regions.filter(r=>r.owner==='friendly').length} / 4 controlados</span></div><div><b>BAIXAS</b><span>${losses} pelotões</span></div></div><button class="btn primary" id="again">NOVA OPERAÇÃO &nbsp; →</button>`;document.getElementById('again').onclick=()=>{document.getElementById('briefing').style.display='none';reset();playing=true}}
function loop(now){let dt=Math.min(.05,(now-last)/1000||0);last=now;update(dt);draw();renderUI();requestAnimationFrame(loop)}
canvas.addEventListener('pointerdown',ev=>{if(!playing||gameOver)return;let p=toWorld(ev.clientX,ev.clientY);
let hit=units.findIndex(u=>dist(u,p)<24);if(hit>=0){selected=hit;renderUI();return}let u=units[selected];if(u){u.order={x:clamp(p.x,20,980),y:clamp(p.y,20,680)};let e=enemies.find(e=>dist(e,p)<28);if(e)u.order={x:e.x,y:e.y};showToast(`Ordem emitida · ${u.name}`);renderUI()}});
canvas.addEventListener('pointermove',ev=>{let p=toWorld(ev.clientX,ev.clientY);mouse=p;});
document.getElementById('unitList').addEventListener('click',ev=>{let card=ev.target.closest('.unit-card');if(card){selected=+card.dataset.id;renderUI()}});
document.getElementById('deploy').onclick=()=>{document.getElementById('briefing').style.display='none';reset();playing=true};
document.getElementById('playPause').onclick=()=>{if(!gameOver){playing=!playing;document.getElementById('playPause').textContent=playing?'Ⅱ':'▶';renderUI()}};
for(let n of [1,2,3])document.getElementById('speed'+n).onclick=()=>{speed=n;document.querySelectorAll('[id^="speed"]').forEach(b=>b.classList.remove('active'));document.getElementById('speed'+n).classList.add('active')};
document.getElementById('reinforce').onclick=()=>{if(supply>=60&&units.length<7){supply-=60;let id=units.length;units.push(makeUnit(id,145+rand(-10,20),350+rand(-40,40)));selected=units.length-1;addEvent(timeLabel(),'Reforços chegaram à base.');showToast('Reforço aliado disponível');renderUI()}};
document.getElementById('rally').onclick=()=>{for(let u of units){u.order={x:150+rand(-20,25),y:370+rand(-70,70)}}showToast('Unidades reagruparam no ponto seguro')};
document.getElementById('newGame').onclick=()=>{document.getElementById('briefing').style.display='grid';reset();playing=false};
window.addEventListener('resize',resize);resize();reset();playing=false;requestAnimationFrame(loop);
})();

