ive{background:#d1bd7c}.map-coords{position:absolute;right:18px;top:17px;font-size:9px;color:#9aa793}.map-hint{position:absolute;bottom:17px;left:18px;padding:9px 11px;background:#111a14cc;border:1px solid #354238;border-radius:5px;font-size:10px}.side{width:330px;display:flex;flex-direction:column;border-left:1px solid #354037;background:#151d17}.side-section{border-bottom:1px solid #303a31;padding:16px}.side-section.intel{flex:1}.section-head{display:flex;justify-content:space-between;align-i

@media(max-width:850px){.topbar{height:58px;padding:0 12px}.brand{min-width:auto}.op-label{display:none}.hud{gap:12px}.hud-stat:nth-child(3),.hud-stat:nth-child(4){display:none}.side{width:240px}.main{height:calc(100dvh - 117px)}}

@media(max-width:620px){.main{flex-direction:column-reverse}.side{width:100%;height:205px;flex:none;border-left:0;border-top:1px solid #354037;display:grid;grid-template-columns:1fr 1fr;overflow:hidden}.side-section{padding:9px 10px}.side-section.intel{grid-column:2}.side-section.units{grid-column:2}.side-section.mission{grid-column:1;grid-row:1}.side-section.feed{display:none}.unit-card:not(.selected){display:none}.bottom{height:59px;padding:0 8px}.selected-summary{min-width:120px}.orders-label,.sound-note{display:none}.map-legend{left:8px;top:8px}.map-hint{left:8px;bottom:8px}.briefing-grid{grid-template-columns:1fr}.modal{padding:18px}}

/* Interface simplificada: prioridade para mapa, objetivos e ordens. */
.topbar{height:58px;gap:14px;padding:0 16px}.brand{min-width:auto;gap:9px}.brand-mark{width:30px;height:30px;border-radius:6px}.brand-sub,.op-label,.map-coords,.sound-note{display:none}.hud{gap:16px}.status-pill{padding:5px 8px}.main{height:calc(100dvh - 106px)}.map-legend{left:12px;top:12px;gap:10px;padding:7px 9px;background:#111a14e8;border:0;border-radius:4px}.map-hint{left:12px;bottom:12px;padding:7px 9px;border:0;background:#111a14d9;border-radius:4px}.side{border-left:1px solid var(--line)}.side-section{padding:14px}.mission-card{border-radius:5px}.section-title{font-size:12px}.intel-row{padding:5px 0}.intel-row span:last-child{max-width:60%;text-align:right}.btn,.ctrl,.country-btn{border-radius:4px}.bottom{height:48px;padding:0 14px}.selected-symbol{border-radius:4px}


@media(max-width:760px){.topbar{height:54px;padding:0 10px}.brand-title{font-size:11px}.hud{gap:9px}.hud-stat{min-width:auto}.hud-label{font-size:8px}.hud-value{font-size:12px}.status-pill{font-size:8px;padding:4px 6px}.main{height:calc(100dvh - 98px)}.map-legend{font-size:8px}.side-section{padding:10px}.intel-row{font-size:9px}.bottom{height:44px;padding:0 8px}.orders-label{display:none}}
